import { dateFromNowWithDaysGap, formatDateToFormat } from '~/utils/formatDateToFormat';

// Six days back plus today is the inclusive 7-day window the dashboards open on when the URL carries
// no explicit range.
const DEFAULT_WINDOW_DAYS_BACK = 6;

export function defaultDashboardDateRange() {
  // Read the clock once and derive both ends from it. Two separate new Date() reads let a midnight
  // crossing between them push the start onto the previous day, stretching the window to 8 days.
  const now = new Date();
  const startDate = dateFromNowWithDaysGap(now, DEFAULT_WINDOW_DAYS_BACK);
  return {
    startDate: formatDateToFormat(startDate, 'yyyy-MM-dd'),
    endDate: formatDateToFormat(now, 'yyyy-MM-dd'),
  };
}
