import type { LocationQuery } from 'vue-router';

// Only the params the stats endpoints accept are forwarded - anything else in the URL, such as a param
// left over in a stale bookmark, would be rejected with a 422.
export function dashboardQueryParams<T>(query: LocationQuery, defaultRange: { startDate: string; endDate: string }): T {
  return {
    start_date: query.start_date ? query.start_date.toString() : defaultRange.startDate,
    end_date: query.end_date ? query.end_date.toString() : defaultRange.endDate,
    timezone: Intl.DateTimeFormat().resolvedOptions().timeZone,
  } as T;
}
